import openpyxl
# Compare styles between golden and filled for all cells in sheet 32
g=openpyxl.load_workbook('golden.xlsx')['32']
f=openpyxl.load_workbook('mimotable_batch1_0028_template_9835_input_filled.xlsx')['32']
diff=0
for row in g.iter_rows(min_row=1, max_row=9, min_col=1, max_col=29):
    for c in row:
        gc=c
        fc=f[c.coordinate]
        if gc.number_format != fc.number_format:
            print('fmt diff', c.coordinate, gc.number_format, fc.number_format); diff+=1
        if gc.has_style and fc.has_style:
            if gc.fill.fgColor.rgb != fc.fill.fgColor.rgb or gc.fill.patternType != fc.fill.patternType:
                print('fill diff', c.coordinate); diff+=1
            if gc.font.name != fc.font.name or gc.font.sz != fc.font.sz or gc.font.b != fc.font.b:
                print('font diff', c.coordinate); diff+=1
print('diffs', diff)
